import { authenticate } from "../shopify.server";

export const loader = async ({ request }) => {
  const { admin, session } = await authenticate.admin(request);
  // admin.graphql(...) já fala com a loja de session.shop
  return null;
};

export const loader = async ({ request }) => {
  const { admin } = await authenticate.admin(request);

  const response = await admin.graphql(
    `#graphql
    query Products($first: Int!) {
      products(first: $first) {
        nodes { id title status }
      }
    }`,
    { variables: { first: 10 } },
  );

  const { data } = await response.json();
  return { products: data.products.nodes };
};

export const action = async ({ request }) => {
  const { admin } = await authenticate.admin(request);
  const form = await request.formData();

  const response = await admin.graphql(
    `#graphql
    mutation Rename($input: ProductInput!) {
      productUpdate(input: $input) {
        product { id title }
        userErrors { field message }
      }
    }`,
    { variables: { input: { id: form.get("id"), title: form.get("title") } } },
  );

  const { data } = await response.json();
  return { errors: data.productUpdate.userErrors };
};

import { useFetcher } from "react-router";

export default function Page() {
  const fetcher = useFetcher();
  const saving = fetcher.state !== "idle";

  return (
    <button
      disabled={saving}
      onClick={() =>
        fetcher.submit({ id: "gid://shopify/Product/1", title: "Novo" }, { method: "POST" })
      }
    >
      Renomear
    </button>
  );
}

